{
  "name": "@darkjd/opencode-openai-codex-auth",
  "version": "4.11.0",
  "description": "OpenAI ChatGPT (Codex backend) OAuth auth plugin for opencode - use your ChatGPT Plus/Pro subscription instead of API credits",
  "main": "./dist/v2.js",
  "types": "./dist/v2.d.ts",
  "exports": {
    ".": {
      "types": "./dist/v2.d.ts",
      "default": "./dist/v2.js"
    },
    "./legacy": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "type": "module",
  "license": "MIT",
  "author": "Numman Ali",
  "contributors": [
    "JDis03 (active fork maintainer — https://github.com/JDis03)"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JDis03/opencode-openai-codex-auth.git"
  },
  "keywords": [
    "opencode",
    "openai",
    "codex",
    "chatgpt",
    "oauth",
    "gpt-5",
    "plugin",
    "auth",
    "chatgpt-plus",
    "chatgpt-pro"
  ],
  "homepage": "https://github.com/JDis03/opencode-openai-codex-auth#readme",
  "bugs": {
    "url": "https://github.com/JDis03/opencode-openai-codex-auth/issues"
  },
  "scripts": {
    "build": "tsc && cp lib/oauth-success.html dist/lib/",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:ui": "vitest --ui",
    "test:coverage": "vitest run --coverage"
  },
  "files": [
    "dist/",
    "assets/",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.0.150"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.150",
    "@opencode-ai/sdk": "^1.0.150",
    "@opencode/plugin": "^2.0.16",
    "@types/node": "^24.6.2",
    "@vitest/ui": "^3.2.4",
    "typescript": "^5.9.3",
    "vitest": "^3.2.4"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.15",
    "@openauthjs/openauth": "^0.4.3",
    "hono": "^4.10.4",
    "jsonc-parser": "^3.3.1"
  },
  "overrides": {
    "hono": "^4.10.4",
    "vite": "^7.1.12"
  }
}
